changeSet.sql:
CREATE TABLE agent_sessions ( id SERIAL PRIMARY KEY, workspace_id INTEGER NOT NULL REFERENCES agent_workspaces(id) ON DELETE CASCADE,
task TEXT NOT NULL, model TEXT, status TEXT NOT NULL DEFAULT 'queued',
-- What the session is allowed to do when it finishes. open_pull_request BOOLEAN NOT NULL DEFAULT TRUE, deploy_to_dev BOOLEAN NOT NULL DEFAULT FALSE, screenshot_paths JSONB NOT NULL DEFAULT '[]'::jsonb,
-- Execution state. container_id TEXT, branch_name TEXT, pr_url TEXT,
created_by TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, started_at TIMESTAMPTZ, finished_at TIMESTAMPTZ, deployed_at TIMESTAMPTZ,
exit_code INTEGER, error TEXT,
-- Usage, mirrored from the agent's own report. Authoritative -- accounting stays in the request log like any other caller. tokens_in BIGINT NOT NULL DEFAULT 0, tokens_out BIGINT NOT NULL DEFAULT 0, cost_eur NUMERIC(12, 6) NOT NULL DEFAULT 0,
CONSTRAINT agent_sessions_status_check CHECK (status IN ( 'queued', 'starting', 'running', 'paused', 'finalizing', 'succeeded', 'failed', 'cancelled' )) );
-- The scheduler's hot path: find queued work, and find whichever -- session currently occupies a workspace. CREATE INDEX idx_agent_sessions_status_created ON agent_sessions(status, created_at); CREATE INDEX idx_agent_sessions_workspace_status ON agent_sessions(workspace_id, status);
-- At most one session may occupy a workspace. Enforced here as -- well as in the admission query, because a bug in the scheduler -- would otherwise corrupt a working copy rather than raise. -- Finalizing occupies it too: the finalizer container runs git -- in the same working copy on the same volume. CREATE UNIQUE INDEX uq_agent_sessions_active_workspace ON agent_sessions(workspace_id) WHERE status IN ('starting', 'running', 'paused', 'finalizing');

CREATE TABLE agent_events ( id BIGSERIAL PRIMARY KEY, session_id INTEGER NOT NULL REFERENCES agent_sessions(id) ON DELETE CASCADE, ts TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, kind TEXT NOT NULL, payload JSONB NOT NULL DEFAULT '{}'::jsonb,
CONSTRAINT agent_events_kind_check CHECK (kind IN ( 'log', 'status', 'pull_request', 'deploy', 'screenshot', 'capacity', 'error' )) );
-- The UI tails a session by asking for events after an id, so the -- index has to serve (session, id) ordering directly. CREATE INDEX idx_agent_events_session_id ON agent_events(session_id, id);

ALTER TABLE agent_sessions ADD COLUMN trigger_kind TEXT;
ALTER TABLE agent_sessions ADD COLUMN trigger_ref TEXT;

-- The dedup lookup asks "is there already a session for this
-- reference", newest first.
CREATE INDEX idx_agent_sessions_trigger_ref
    ON agent_sessions(trigger_ref, created_at DESC)
 WHERE trigger_ref IS NOT NULL;

rollback.sql:
DROP INDEX IF EXISTS idx_agent_sessions_trigger_ref;
ALTER TABLE agent_sessions DROP COLUMN IF EXISTS trigger_ref;
ALTER TABLE agent_sessions DROP COLUMN IF EXISTS trigger_kind;
